}
const results = tests.map(t => {
  const fails = t.steps.flatMap(s => s.fails.map(f => `第 ${s.step} 則 ${f}`));
  return { json: {
    id: t.id, 測試: t.title, 結果: fails.length ? 'FAIL' : 'PASS',
    失敗原因: fails.join('；') || null,
    訊息: t.steps.map(s => s.text),
    回覆: t.steps.map(s => s.reply),
